/// @brief One-sample t-test against t.test(x, mu).
TEST(RParametricTests, TTestOneSample) {
    using Case = ref::TTestOneSample;
    const auto x = AsVector(Case::kX);
    const auto r = statcpp::t_test(x.begin(), x.end(), Case::kMu0);
    EXPECT_R_FIELD(r.statistic, Case, kStatistic);
    EXPECT_R_FIELD(r.df, Case, kDf);
    EXPECT_R_PVALUE(r.p_value, Case, kPValue);
}

