/// @brief Above the published range only the D statistic is compared.
///
/// The Dallal-Wilkinson approximation is defined for p <= 0.10. statcpp still
/// returns a value there, but it indicates consistency with normality rather
/// than an accurate p-value, so the test asserts only that it stays clearly
/// above every conventional significance level.
TEST(RNonparametricTests, LillieforsTestUpperRange) {
    using Case = ref::LillieforsTestUpperRange;
    const auto x = AsVector(Case::kX);
    const auto r = statcpp::lilliefors_test(x.begin(), x.end());
    EXPECT_R_FIELD(r.statistic, Case, kStatistic);
    EXPECT_GT(r.p_value, 0.10);
    EXPECT_LE(r.p_value, 1.0);
}

/// @brief ks_test_normal forwards to lilliefors_test, so it shares the reference.
///
/// The function is deprecated in statcpp; the deprecation warning is suppressed
/// here because exercising it is the point of this test.
TEST(RNonparametricTests, KsTestNormal) {
    using Case = ref::KsTestNormal;
    const auto x = AsVector(Case::kX);
#if defined(__clang__) || defined(__GNUC__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wdeprecated-declarations"
#endif
    const auto r = statcpp::ks_test_normal(x.begin(), x.end());
#if defined(__clang__) || defined(__GNUC__)
#pragma GCC diagnostic pop
#endif
    EXPECT_R_FIELD(r.statistic, Case, kStatistic);
    EXPECT_R_PVALUE(r.p_value, Case, kPValue);
}

