/// @brief One-way ANOVA and its effect sizes against summary(aov(y ~ g)).
TEST(RAnova, OneWayAnova) {
    using Case = ref::OneWayAnova;
    const auto groups = MakeGroups(Case::kGroupsFlat, Case::kGroupsSizes, Case::kGroupsCount);
    const auto r = statcpp::one_way_anova(groups);
    EXPECT_R_FIELD(r.between.f_statistic, Case, kFStatistic);
    EXPECT_R_PVALUE(r.between.p_value, Case, kPValue);
    EXPECT_R_FIELD(r.between.ss, Case, kSsBetween);
    EXPECT_R_FIELD(r.between.df, Case, kDfBetween);
    EXPECT_R_FIELD(r.between.ms, Case, kMsBetween);
    EXPECT_R_FIELD(r.within.ss, Case, kSsWithin);
    EXPECT_R_FIELD(r.within.df, Case, kDfWithin);
    EXPECT_R_FIELD(r.within.ms, Case, kMsWithin);
    EXPECT_R_FIELD(r.ss_total, Case, kSsTotal);
    EXPECT_R_FIELD(statcpp::eta_squared(r), Case, kEtaSquared);
    EXPECT_R_FIELD(statcpp::omega_squared(r), Case, kOmegaSquared);
    EXPECT_R_FIELD(statcpp::cohens_f(r), Case, kCohensF);
}

/// @brief Tukey HSD against TukeyHSD(aov(y ~ g)).
TEST(RAnova, TukeyHsd) {
    using Case = ref::TukeyHsd;
    const auto groups = MakeGroups(Case::kGroupsFlat, Case::kGroupsSizes, Case::kGroupsCount);
    const auto anova = statcpp::one_way_anova(groups);
    const auto r = statcpp::tukey_hsd(anova, groups);
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.mean_diff; }), Case, kMeanDiff);
    EXPECT_R_PVALUE_RANGE(Project(r, [](const auto& c) { return c.p_value; }), Case, kPValue);
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.lower; }), Case, kLower);
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.upper; }), Case, kUpper);
}

/// @brief Bonferroni post-hoc comparisons against the pooled-MSE closed form.
TEST(RAnova, BonferroniPosthoc) {
    using Case = ref::BonferroniPosthoc;
    const auto groups = MakeGroups(Case::kGroupsFlat, Case::kGroupsSizes, Case::kGroupsCount);
    const auto anova = statcpp::one_way_anova(groups);
    const auto r = statcpp::bonferroni_posthoc(anova);
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.mean_diff; }), Case, kMeanDiff);
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.statistic; }), Case, kStatistic);
    EXPECT_R_PVALUE_RANGE(Project(r, [](const auto& c) { return c.p_value; }), Case, kPValue);
    // The same p-values are produced by R's pairwise.t.test.
    EXPECT_R_PVALUE_RANGE(Project(r, [](const auto& c) { return c.p_value; }), Case, kCrossCheck);
}

/// @brief Scheffe post-hoc comparisons against the F-based closed form.
TEST(RAnova, ScheffePosthoc) {
    using Case = ref::ScheffePosthoc;
    const auto groups = MakeGroups(Case::kGroupsFlat, Case::kGroupsSizes, Case::kGroupsCount);
    const auto anova = statcpp::one_way_anova(groups);
    const auto r = statcpp::scheffe_posthoc(anova);
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.mean_diff; }), Case, kMeanDiff);
    // statcpp keeps the signed t statistic here; F = t^2 / df_between is used
    // only to obtain the p-value.
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.statistic; }), Case, kStatistic);
    const double df_between = anova.between.df;
    EXPECT_R_RANGE(Project(r, [df_between](const auto& c) { return c.statistic * c.statistic / df_between; }),
                   Case, kFStatistic);
    EXPECT_R_PVALUE_RANGE(Project(r, [](const auto& c) { return c.p_value; }), Case, kPValue);
}

/// @brief Comparisons against a control group, using statcpp's Bonferroni approximation.
TEST(RAnova, DunnettPosthoc) {
    using Case = ref::DunnettPosthoc;
    const auto groups = MakeGroups(Case::kGroupsFlat, Case::kGroupsSizes, Case::kGroupsCount);
    const auto anova = statcpp::one_way_anova(groups);
    const auto r = statcpp::dunnett_posthoc(anova, Case::kControlGroup);
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.mean_diff; }), Case, kMeanDiff);
    EXPECT_R_RANGE(Project(r, [](const auto& c) { return c.statistic; }), Case, kStatistic);
    EXPECT_R_PVALUE_RANGE(Project(r, [](const auto& c) { return c.p_value; }), Case, kPValue);
}

/// @brief Two-way ANOVA and partial eta squared against summary(aov(y ~ a * b)).
TEST(RAnova, TwoWayAnova) {
    using Case = ref::TwoWayAnova;
    std::vector<std::vector<std::vector<double>>> data(
        Case::kLevelsA, std::vector<std::vector<double>>(Case::kLevelsB));
    std::size_t offset = 0;
    for (std::size_t a = 0; a < Case::kLevelsA; ++a) {
        for (std::size_t b = 0; b < Case::kLevelsB; ++b) {
            data[a][b].assign(Case::kValues + offset, Case::kValues + offset + Case::kReps);
            offset += Case::kReps;
        }
    }
    const auto r = statcpp::two_way_anova(data);
    EXPECT_R_FIELD(r.factor_a.f_statistic, Case, kFA);
    EXPECT_R_PVALUE(r.factor_a.p_value, Case, kPA);
    EXPECT_R_FIELD(r.factor_b.f_statistic, Case, kFB);
    EXPECT_R_PVALUE(r.factor_b.p_value, Case, kPB);
    EXPECT_R_FIELD(r.interaction.f_statistic, Case, kFInteraction);
    EXPECT_R_PVALUE(r.interaction.p_value, Case, kPInteraction);
    EXPECT_R_FIELD(r.factor_a.ss, Case, kSsA);
    EXPECT_R_FIELD(r.factor_b.ss, Case, kSsB);
    EXPECT_R_FIELD(r.interaction.ss, Case, kSsInteraction);
    EXPECT_R_FIELD(r.error.ss, Case, kSsError);
    EXPECT_R_FIELD(statcpp::partial_eta_squared_a(r), Case, kPartialEtaSquaredA);
    EXPECT_R_FIELD(statcpp::partial_eta_squared_b(r), Case, kPartialEtaSquaredB);
    EXPECT_R_FIELD(statcpp::partial_eta_squared_interaction(r), Case, kPartialEtaSquaredInteraction);
}

/// @brief One-way ANCOVA against summary(aov(y ~ x + g)).
TEST(RAnova, OneWayAncova) {
    using Case = ref::OneWayAncova;
    std::vector<std::vector<std::pair<double, double>>> groups(Case::kYCount);
    std::size_t offset = 0;
    for (std::size_t g = 0; g < Case::kYCount; ++g) {
        for (std::size_t i = 0; i < Case::kYSizes[g]; ++i) {
            groups[g].emplace_back(Case::kYFlat[offset + i], Case::kXFlat[offset + i]);
        }
        offset += Case::kYSizes[g];
    }
    const auto r = statcpp::one_way_ancova(groups);
    EXPECT_R_FIELD(r.ss_covariate, Case, kSsCovariate);
    EXPECT_R_FIELD(r.df_covariate, Case, kDfCovariate);
    EXPECT_R_FIELD(r.f_covariate, Case, kFCovariate);
    EXPECT_R_PVALUE(r.p_covariate, Case, kPCovariate);
    EXPECT_R_FIELD(r.ss_treatment, Case, kSsTreatment);
    EXPECT_R_FIELD(r.df_treatment, Case, kDfTreatment);
    EXPECT_R_FIELD(r.f_treatment, Case, kFTreatment);
    EXPECT_R_PVALUE(r.p_treatment, Case, kPTreatment);
    EXPECT_R_FIELD(r.ss_error, Case, kSsError);
    EXPECT_R_FIELD(r.df_error, Case, kDfError);
}

